#include <atomic>

void raiseTo(std::atomic<int>& maximum, int candidate)
{
    int seen{ maximum.load() };
    while (candidate > seen && !maximum.compare_exchange_weak(seen, candidate))
    {
    }
}

class SpinLock
{
public:
    void lock()
    {
        while (m_flag.test_and_set(std::memory_order_acquire))
        {
            m_flag.wait(true, std::memory_order_relaxed);
        }
    }

    void unlock()
    {
        m_flag.clear(std::memory_order_release);
        m_flag.notify_one();
    }

private:
    std::atomic_flag m_flag{};
};

unitTests:
#include <mutex>
#include <thread>
TEST("raiseTo, single thread") { std::atomic<int> m{ 5 }; raiseTo(m, 3); CHECK_EQ(m.load(), 5); raiseTo(m, 9); CHECK_EQ(m.load(), 9); raiseTo(m, 9); CHECK_EQ(m.load(), 9); }
TEST("raiseTo, many threads: the largest candidate wins") {
    for (int round{ 0 }; round < 5; ++round)
    {
        std::atomic<int> m{ 0 };
        {
            std::vector<std::jthread> threads;
            for (int t{ 0 }; t < 8; ++t) threads.emplace_back([&m, t] { for (int i{ 0 }; i < 20000; ++i) raiseTo(m, (i * 7 + t * 13) % 100003); });
        }
        int expected{ 0 };
        for (int t{ 0 }; t < 8; ++t) for (int i{ 0 }; i < 20000; ++i) expected = std::max(expected, (i * 7 + t * 13) % 100003);
        CHECK_EQ(m.load(), expected);
    }
}
TEST("SpinLock protects a plain int") {
    SpinLock lock{};
    int counter{ 0 };
    {
        std::vector<std::jthread> threads;
        for (int t{ 0 }; t < 8; ++t) threads.emplace_back([&] { for (int i{ 0 }; i < 20000; ++i) { const std::lock_guard guard{ lock }; ++counter; } });
    }
    CHECK_EQ(counter, 160000);
}

